import { createHash } from 'node:crypto';
import { createReadStream } from 'node:fs';
import path from 'node:path';

export interface McpToolSchema {
  name: string;
  description?: string;
  inputSchema: Record<string, unknown>;
}

export interface SupplyChainPinManifest {
  mcpServers: Record<string, { expectedToolsHashSha256: string; pinnedPackageDigest: string }>;
  models: Record<string, { filename: string; sha256: string }>;
}

// Chuẩn hóa JSON theo thứ tự key alphabet để hash không bị lệch do thứ tự trường
function canonicalStringify(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map(canonicalStringify).join(',')}]`;
  }
  if (value && typeof value === 'object') {
    const entries = Object.entries(value as Record<string, unknown>)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([k, v]) => `${JSON.stringify(k)}:${canonicalStringify(v)}`);
    return `{${entries.join(',')}}`;
  }
  return JSON.stringify(value);
}

export function computeMcpToolsHash(tools: McpToolSchema[]): string {
  const normalized = [...tools].sort((a, b) => a.name.localeCompare(b.name));
  const canonical = canonicalStringify(normalized);
  return createHash('sha256').update(canonical, 'utf8').digest('hex');
}

export function assertMcpNoRugPull(
  serverName: string,
  liveTools: McpToolSchema[],
  manifest: SupplyChainPinManifest
): void {
  const pin = manifest.mcpServers[serverName];
  if (!pin) {
    throw new Error(`[SUPPLY_CHAIN_BLOCK] MCP server '${serverName}' chưa có trong mcp-pin-manifest.json`);
  }
  const liveHash = computeMcpToolsHash(liveTools);
  if (liveHash !== pin.expectedToolsHashSha256) {
    throw new Error(
      `[MCP_RUG_PULL_DETECTED] Schema tools/list của '${serverName}' đã bị biến đổi! ` +
        `Expected=${pin.expectedToolsHashSha256}, Got=${liveHash}`
    );
  }
}

const ALLOWED_WEIGHT_EXTENSIONS = new Set(['.safetensors', '.onnx', '.gguf']);

export async function verifyModelArtifactSafe(
  modelKey: string,
  artifactPath: string,
  manifest: SupplyChainPinManifest
): Promise<void> {
  const ext = path.extname(artifactPath).toLowerCase();
  if (!ALLOWED_WEIGHT_EXTENSIONS.has(ext)) {
    throw new Error(
      `[PICKLE_FORBIDDEN] Từ chối nạp tệp trọng số '${artifactPath}' (chỉ chấp nhận .safetensors, .onnx, .gguf)`
    );
  }
  const expected = manifest.models[modelKey];
  if (!expected) {
    throw new Error(`[AIBOM_MISSING] Mô hình '${modelKey}' chưa được khai báo checksum SHA-256`);
  }
  const hash = createHash('sha256');
  await new Promise<void>((resolve, reject) => {
    const stream = createReadStream(artifactPath);
    stream.on('data', (chunk) => hash.update(chunk));
    stream.on('error', reject);
    stream.on('end', () => resolve());
  });
  const actualSha256 = hash.digest('hex');
  if (actualSha256 !== expected.sha256) {
    throw new Error(
      `[MODEL_TAMPERED] Checksum file '${artifactPath}' không khớp AIBOM! Expected=${expected.sha256}, Got=${actualSha256}`
    );
  }
}
